begin;
select plan(78);

select has_table('public','trackers','trackers exists');
select has_table('public','grade_entries','de-identified grade entries exist');
select has_table('public','public_grade_submissions','public submission receipts exist');
select has_table('public','tracker_templates','tracker templates exist');
select has_table('public','tracker_template_stages','tracker template stages exist');
select has_table('public','important_dates','important dates exist');
select has_table('public','stage_links','stage links exist');
select has_function('public','submit_grade_upload',array['uuid','numeric[]'],'grade upload RPC exists');
select has_function('public','submit_public_grade_upload',array['text','text','text','text','text','text','numeric[]'],'public grade upload RPC exists');
select has_function('public','resolve_grade_course',array['text','text','text'],'course resolution RPC exists');
select has_function('public','create_academic_term',array['text','text','date','date','boolean'],'academic term creation RPC exists');
select has_function('public','delete_course_term_grades',array['uuid','text'],'course-term grade deletion RPC exists');
select has_function('public','import_important_dates',array['text','text','jsonb'],'important date import RPC exists');
select has_function('public','save_tracker_template',array['uuid','text','text','tracker_type','tracker_category','text','jsonb'],'template save RPC exists');
select has_function('public','create_tracker_from_template',array['uuid','text','text','date'],'template application RPC exists');
select col_is_pk('public','profiles','id','profiles use auth user primary key');
select ok((select relrowsecurity from pg_class where oid='public.trackers'::regclass),'trackers RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.grade_entries'::regclass),'grade entries RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.public_grade_submissions'::regclass),'public submission receipts use RLS');
select ok((select relrowsecurity from pg_class where oid='public.tracker_templates'::regclass),'tracker templates use RLS');
select ok((select relrowsecurity from pg_class where oid='public.tracker_template_stages'::regclass),'tracker template stages use RLS');
select ok((select relrowsecurity from pg_class where oid='public.important_dates'::regclass),'important dates use RLS');
select ok((select relrowsecurity from pg_class where oid='public.stage_links'::regclass),'stage links use RLS');
select is(private.normalize_course_code('BUSI1100'),'BUSI 1100U','Course normalization supplies spacing and undergraduate suffix');
select results_eq($$select count(*)::bigint from public.academic_terms where is_current$$,array[1::bigint],'one current term');
select results_eq($$select public.create_academic_term('w27','Winter 2027',date '2027-01-04',date '2027-04-30',false)$$,array['W27'::text],'Dean can create and normalize an academic term');
select results_eq($$select count(*)::bigint from public.academic_terms where code='W27' and name='Winter 2027' and not is_current$$,array[1::bigint],'New academic term is stored without changing the current term');
select results_eq($$select average_threshold::numeric from public.grade_benchmark_settings where scope='faculty'$$,array[70::numeric],'prototype average threshold seeded');
select throws_ok($$insert into public.stages(tracker_id,title,due_date,is_required,status,sort_order,created_by) values('20000000-0000-0000-0000-000000000001','Invalid','2026-12-01',true,'skipped',99,'00000000-0000-0000-0000-000000000001')$$,'23514',null,'required stages cannot be skipped');
select throws_ok($$insert into public.grade_entries(grade_upload_id,source_row,final_grade) values(gen_random_uuid(),1,50)$$,'23503',null,'orphan grade entries rejected');
select throws_ok($$insert into public.stage_links(tracker_id,stage_id,title,url,created_by) values('20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','Unsafe link','javascript:alert(1)','00000000-0000-0000-0000-000000000001')$$,'23514',null,'stage links reject non-HTTP protocols');

set local role authenticated;
set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000001';
select results_eq($$select count(*)::bigint from public.trackers$$,array[3::bigint],'Dean can read every tracker');
select lives_ok($$select public.save_tracker_template(null,'Faculty review cycle','Reusable review workflow','general','Administrative','faculty','[{"title":"Request submission","description":"Send request","due_offset_days":0,"is_required":true},{"title":"Complete review","description":"Review response","due_offset_days":7,"is_required":true}]'::jsonb)$$,'Dean can create a faculty template');
select results_eq($$select count(*)::bigint from public.tracker_templates where name='Faculty review cycle' and scope='faculty'$$,array[1::bigint],'Faculty template is stored once');
select lives_ok($$select public.import_important_dates('2026-27','Important Dates 2026-27.xlsx','[{"semester":"Fall","starts_on":"2026-09-08","ends_on":"2026-09-08","short_name":"Fall Lectures Begin","description":"Lectures begin."},{"semester":"Fall","starts_on":"2026-09-08","ends_on":"2026-09-08","short_name":"Fall Fees Due","description":"Fall semester fees due."}]'::jsonb)$$,'Dean can import important dates');
select results_eq($$select count(*)::bigint from public.important_dates where academic_year='2026-27'$$,array[2::bigint],'Important date import stores independent same-date events');
select lives_ok($$insert into public.stage_links(tracker_id,stage_id,title,url) values('20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','Faculty guide','https://example.test/faculty-guide'),('20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','Submission portal','https://example.test/submit')$$,'Tracker manager can attach multiple links to one stage');
select results_eq($$select count(*)::bigint from public.stage_links where stage_id='30000000-0000-0000-0000-000000000001'$$,array[2::bigint],'Multiple stage links are stored independently');

set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000002';
select results_eq($$select count(*)::bigint from public.trackers$$,array[1::bigint],'Instructor sees only an assigned tracker');
select results_eq($$select count(*)::bigint from public.course_terms$$,array[1::bigint],'Instructor sees only their assigned course term');
select results_eq($$select count(*)::bigint from public.tracker_templates where name='Faculty review cycle'$$,array[1::bigint],'Instructor can read faculty templates');
select throws_ok($$select public.save_tracker_template(null,'Unauthorized shared template','Not allowed','general','Other','faculty','[{"title":"Stage one","due_offset_days":0,"is_required":true}]'::jsonb)$$,'42501','Only deans can create faculty templates.','Instructor cannot create a faculty template');
select lives_ok($$select public.save_tracker_template(null,'My review template','Personal reusable workflow','general','Academic','personal','[{"title":"Prepare materials","due_offset_days":-2,"is_required":true},{"title":"Hold review","due_offset_days":0,"is_required":true}]'::jsonb)$$,'Instructor can create a personal template');
select results_eq($$select count(*)::bigint from public.tracker_templates where name in ('Faculty review cycle','My review template')$$,array[2::bigint],'Instructor sees shared and owned personal templates');
select results_eq($$select count(*)::bigint from public.important_dates where academic_year='2026-27'$$,array[2::bigint],'Instructor can read managed important dates');
select results_eq($$select count(*)::bigint from public.stage_links where stage_id='30000000-0000-0000-0000-000000000001'$$,array[2::bigint],'Users with tracker access can read stage links');
select lives_ok($$delete from public.stage_links where stage_id='30000000-0000-0000-0000-000000000001'$$,'Non-manager link deletion is safely filtered by RLS');
select results_eq($$select count(*)::bigint from public.stage_links where stage_id='30000000-0000-0000-0000-000000000001'$$,array[2::bigint],'Non-manager cannot remove stage links');
select throws_ok($$select public.import_important_dates('2027-28','dates.xlsx','[{"semester":"Fall","starts_on":"2027-09-01","ends_on":"2027-09-01","short_name":"Test Date","description":"Test date."}]'::jsonb)$$,'42501','Only deans can manage important dates.','Instructor cannot import important dates');
select lives_ok($$select public.create_tracker_from_template((select id from public.tracker_templates where name='Faculty review cycle'),'September review','',date '2026-09-10')$$,'Instructor can create a tracker from a faculty template');
select results_eq($$select count(*)::bigint from public.trackers where title='September review' and created_by=(select auth.uid())$$,array[1::bigint],'Template creates an owned tracker');
select results_eq($$select array_agg(due_date order by sort_order) from public.stages where tracker_id=(select id from public.trackers where title='September review')$$,$$values(array[date '2026-09-10',date '2026-09-17']::date[])$$,'Template offsets generate stage due dates');
select results_eq($$select count(*)::bigint from public.stages where tracker_id=(select id from public.trackers where title='September review') and status='pending'$$,array[2::bigint],'Template-created stages begin pending');
select lives_ok($$select public.submit_grade_upload('50000000-0000-0000-0000-000000000001',array[85,75,65,45]::numeric[])$$,'Instructor can submit de-identified grades for their course');
select results_eq($$select (public.submit_grade_upload('50000000-0000-0000-0000-000000000001',array[85,75,65,45]::numeric[])->>'duplicate')::boolean$$,array[true],'Identical grade data is recognized as a duplicate');
select results_eq($$select count(*)::bigint from public.grade_uploads where course_term_id='50000000-0000-0000-0000-000000000001'$$,array[1::bigint],'Duplicate grade data does not create another upload version');
select results_eq($$select public.delete_course_term_grades('40000000-0000-0000-0000-000000000001','F26')$$,array[1],'Instructor can delete grade-upload history for their assigned course term');
select results_eq($$select count(*)::bigint from public.grade_uploads where course_term_id='50000000-0000-0000-0000-000000000001'$$,array[0::bigint],'Deleting course-term grades removes the derived analytics source');
select lives_ok($$select public.resolve_grade_course('INFR1100','Network Fundamentals','F26')$$,'Instructor can include a genuinely new normalized course');
select results_eq($$select public.resolve_grade_course('INFR 1100','Network Fundamentals','F26')->>'course_code'$$,array['INFR 1100U'::text],'Missing undergraduate suffix resolves to the canonical stored course');
select throws_ok($$select public.submit_grade_upload('50000000-0000-0000-0000-000000000002',array[85,75]::numeric[])$$,'42501','Not authorized for this course term','Instructor cannot submit grades for another course');
select throws_ok($$select public.delete_course_term_grades('40000000-0000-0000-0000-000000000002','F26')$$,'42501','Not authorized to delete grades for this course term.','Instructor cannot delete another instructor''s grade data');
select throws_ok($$select public.create_academic_term('F27','Fall 2027',date '2027-09-01',date '2027-12-20',false)$$,'42501','Only deans and academic directors can create academic terms.','Instructor cannot create an academic term');

set local role anon;
select throws_ok($$select count(*) from public.public_grade_submissions$$,'42501',null,'Anonymous callers cannot read public submission receipts');
select throws_ok($$select public.submit_public_grade_upload('INFT 1020U','BUSI 1100U','Intro','F26','Alex Mercer','alex.mercer@ontariotechu.ca',array[90,80]::numeric[])$$,'P0001','The entered course code does not match the uploaded file.','Entered and file course codes must agree');
select throws_ok($$select public.submit_public_grade_upload('INFT 1020U','INFT 1020U','Intro','S26','Alex Mercer','alex.mercer@ontariotechu.ca',array[90,80]::numeric[])$$,'P0001','The semester in the uploaded file is not configured.','Public uploads reject a file term that is not configured');
select throws_ok($$select public.submit_public_grade_upload('INFT 1020U','INFT 1020U','Intro','F26','Alex Mercer','other@ontariotechu.ca',array[90,80]::numeric[])$$,'P0001','Course or faculty details could not be verified.','Public submitter must match the assigned faculty email');
select results_eq($$select (public.submit_public_grade_upload('INFT1020','INFT 1020U','Intro','F26','Alex Mercer','alex.mercer@ontariotechu.ca',array[90,80]::numeric[])->>'duplicate')::boolean$$,array[false],'Verified public faculty submission accepts equivalent code spacing and missing U');
select results_eq($$select (public.submit_public_grade_upload('INFT 1020U','INFT 1020U','Intro','F26','Dr. Alex Mercer','ALEX.MERCER@ONTARIOTECHU.CA',array[90,80]::numeric[])->>'duplicate')::boolean$$,array[true],'Identical public submission is recognized as a duplicate');
select results_eq($$select (public.submit_public_grade_upload('CSCI2000','CSCI 2000U','Computing Foundations','W26','Alex Mercer','alex.mercer@ontariotechu.ca',array[88,78]::numeric[])->>'created_course')::boolean$$,array[true],'Verified public faculty can include a genuinely new course for the uploaded file term');
reset role;

set local role authenticated;
set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000001';
select lives_ok($$delete from public.stage_links where stage_id='30000000-0000-0000-0000-000000000001'$$,'Tracker manager can remove attached links');
reset role;

select results_eq($$select count(*)::bigint from public.public_grade_submissions$$,array[2::bigint],'Duplicate public submission does not create another receipt');
select results_eq($$select count(*)::bigint from public.grade_uploads where course_term_id='50000000-0000-0000-0000-000000000001' and submission_source='public'$$,array[1::bigint],'Public submission creates one attributed grade upload');
select results_eq($$select count(*)::bigint from public.tracker_templates where name in ('Faculty review cycle','My review template')$$,array[2::bigint],'Shared and personal templates persist for their owners');
select results_eq($$select count(*)::bigint from public.courses where code='CSCI 2000U' and title='Computing Foundations'$$,array[1::bigint],'Publicly submitted new course stores canonical code and uploaded title');
select results_eq($$select count(*)::bigint from public.course_terms ct join public.courses c on c.id=ct.course_id where c.code='CSCI 2000U' and ct.instructor_id='00000000-0000-0000-0000-000000000002' and ct.term_code='W26'$$,array[1::bigint],'New public course is assigned to the verified faculty member in the uploaded file term');
select results_eq($$select count(*)::bigint from public.courses where code='INFR 1100U'$$,array[1::bigint],'Authenticated new-course resolution persists the canonical course');
select results_eq($$select count(*)::bigint from public.stage_links$$,array[0::bigint],'Removed stage links no longer appear');

select * from finish();
rollback;
